from itertools import combinations
from typing import Callable, Tuple

Cell = Tuple[int, int]


def cyclic(n: int) -> Callable[[int, int], int]:
    return lambda i, j: (i + j) % n


def adjacent(M, p: Cell, q: Cell) -> bool:
    (i, j), (k, l) = p, q
    return i == k or j == l or M(i, j) == M(k, l)


def count_cliques(M, n: int, k: int) -> int:
    cells = [(i, j) for i in range(n) for j in range(n)]
    return sum(
        1 for S in combinations(cells, k)
        if all(adjacent(M, S[a], S[b])
               for a in range(k) for b in range(a + 1, k))
    )


def main() -> None:
    n = 5
    M = cyclic(n)
    tri = count_cliques(M, n, 3)
    tet = count_cliques(M, n, 4)
    print(f'triangles: true={tri}, proposed n^2(n-1)^2={n**2*(n-1)**2}')
    print(f'tetrahedra: true={tet}, proposed (n-1)^3 n^2={(n-1)**3*n**2}')
    assert tri == 250 and tet == 75
    print('Refuted: proposed formulas do not match the true counts.')


if __name__ == '__main__':
    main()

